function unsafeDecode(str) {
  return decodeURIComponent(str);
}
export function parseQueryString(searchOrHash) {
  const first = searchOrHash.slice(0, 1);
  const qs = first === '#' || first === '?' ? searchOrHash.slice(1) : searchOrHash;
  const parts = qs.split('&').filter(x => x !== '');
  const decode = s => unsafeDecode(s.replace(/\+/g, ' '));
  const out = [];
  for (const kv of parts) {
    const [k, ...rest] = kv.split('=');
    if (!k) continue;
    if (rest.length === 0) out.push([decode(k), null]);else if (rest.length === 1) out.push([decode(k), decode(rest[0] ?? '')]);
  }
  return out;
}
export function curQuerystring() {
  return parseQueryString(window.location.search);
}
export function lookupQueryStringValue(qs, k) {
  for (const [key, val] of qs) {
    if (key === k) return val;
  }
  return null;
}
export function encodeTag(tag) {
  return encodeURIComponent(tag.replace(/\+/g, '%2B'));
}
export function fromNullableStr(s) {
  return s ?? '';
}
export function normalizeTags(tags) {
  return tags?.replace(/,/g, ' ').replace(/\s+/g, ' ').trim() ?? '';
}
export function apiErrorMsg(t, status, bodyText) {
  const body = bodyText.trim();
  if (!body.includes('\n') && !body.includes('doctype html') && body.length > 0) {
    return t('error.errorWithMsg', {
      status,
      msg: body
    });
  }
  return t('error.error', {
    status
  });
}

/**
 * Generates a short, non-cryptographic hash from a string.
 * @param str - The input string to hash.
 * @returns A short alphanumeric string hash.
 */
export function getShortHash(str) {
  let hash = 5381;
  let i = str.length;
  while (i) {
    hash = hash * 33 ^ str.charCodeAt(--i);
  }

  // Convert to an unsigned 32-bit integer, then to a base36 string
  return (hash >>> 0).toString(36);
}